import React from "react";
import { Link } from "react-router-dom";

const placeholderImg =
  "data:image/svg+xml;utf8," +
  encodeURIComponent(
    `<svg xmlns='http://www.w3.org/2000/svg' width='400' height='400'><rect width='100%' height='100%' fill='#221D19'/><text x='50%' y='50%' font-family='sans-serif' font-size='16' fill='#8A8177' text-anchor='middle'>Khussa Photo</text></svg>`
  );

const ProductCard = ({ product }) => {
  const image = product.images?.[0] || placeholderImg;

  return (
    <Link to={`/product/${product.slug}`} className="group block">
      <div className="aspect-square overflow-hidden bg-charcoal border border-brass/10">
        <img
          src={image}
          alt={product.name}
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
      </div>
      <div className="pt-3">
        <h3 className="text-ivory text-sm">{product.name}</h3>
        <div className="flex items-center gap-2 mt-1">
          <span className="text-brass text-sm">Rs. {product.price?.toLocaleString()}</span>
          {product.compareAtPrice && (
            <span className="text-stone text-xs line-through">
              Rs. {product.compareAtPrice.toLocaleString()}
            </span>
          )}
        </div>
      </div>
    </Link>
  );
};

export default ProductCard;
